import SidebarGroup from "../../components/ui/sidebar/group.marko";
import SidebarGroupLabel from "../../components/ui/sidebar/group-label.marko";
import SidebarMenu from "../../components/ui/sidebar/menu.marko";
import SidebarMenuItem from "../../components/ui/sidebar/menu-item.marko";
import SidebarMenuButton from "../../components/ui/sidebar/menu-button.marko";
import Collapsible from "../../components/ui/collapsible/collapsible.marko";

export interface NavMainLeafItem {
  id: string;
  title: string;
  url: string;
}

export interface NavMainItem {
  id: string;
  title: string;
  url: string;
  /** SVG path `d` attribute(s) for a 24x24 lucide-style icon, rendered inline. */
  icon: string;
  isActive?: boolean;
  items: NavMainLeafItem[];
}

export interface Input {
  items: NavMainItem[];
}

// NOTE: our sidebar sub-parts have no SidebarMenuSub / SidebarMenuSubButton
// equivalents yet, so the indented sub-menu list is composed here from
// Collapsible + plain markup, following the pattern established in
// blocks/sidebar-07/nav-main.marko. Deviation from the source, noted per
// block-porting rules.
//
// Our SidebarMenuButton also has no `tooltip` prop (the source's
// icon-only-collapsed hover tooltip), so it is omitted here.

<SidebarGroup>
  <SidebarGroupLabel>Platform</SidebarGroupLabel>
  <SidebarMenu>
    <for|item| of=input.items by=(item) => item.id>
      <Collapsible defaultOpen=(!!item.isActive) class="group/collapsible">
        <@trigger|attrs|>
          <SidebarMenuItem>
            <SidebarMenuButton ...attrs>
              <svg
                xmlns="http://www.w3.org/2000/svg"
                width="24"
                height="24"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                stroke-width="2"
                stroke-linecap="round"
                stroke-linejoin="round"
              >
                <path d=item.icon/>
              </svg>
              <span>${item.title}</span>
              <svg
                xmlns="http://www.w3.org/2000/svg"
                width="24"
                height="24"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                stroke-width="2"
                stroke-linecap="round"
                stroke-linejoin="round"
                class="ml-auto transition-transform duration-200 group-data-[state=open]/collapsible:rotate-90"
              >
                <path d="m9 18 6-6-6-6"/>
              </svg>
            </SidebarMenuButton>
          </SidebarMenuItem>
        </@trigger>
        <@content>
          <ul
            class="mx-3.5 flex min-w-0 translate-x-px flex-col gap-1 border-l border-sidebar-border px-2.5 py-0.5"
          >
            <for|leaf| of=item.items by=(leaf) => leaf.id>
              <li class="group/menu-sub-item relative">
                <a
                  href=leaf.url
                  class="flex h-7 min-w-0 -translate-x-px items-center gap-2 overflow-hidden rounded-md px-2 text-sm text-sidebar-foreground outline-none ring-sidebar-ring hover:bg-sidebar-accent hover:text-sidebar-accent-foreground focus-visible:ring-2 active:bg-sidebar-accent active:text-sidebar-accent-foreground"
                >
                  <span>${leaf.title}</span>
                </a>
              </li>
            </for>
          </ul>
        </@content>
      </Collapsible>
    </for>
  </SidebarMenu>
</SidebarGroup>

import SidebarGroup from "../../components/ui/sidebar/group.marko";
import SidebarMenu from "../../components/ui/sidebar/menu.marko";
import SidebarMenuItem from "../../components/ui/sidebar/menu-item.marko";
import SidebarMenuButton from "../../components/ui/sidebar/menu-button.marko";

export interface NavSecondaryItem {
  id: string;
  title: string;
  url: string;
  /** SVG path `d` attribute(s) for a 24x24 lucide-style icon, rendered inline. */
  icon: string;
}

export interface Input {
  items: NavSecondaryItem[];
  class?: string;
}

// NOTE: our SidebarGroup has no dedicated SidebarGroupContent sub-part, so
// the group's children are rendered directly, following the pattern used
// throughout the sidebar block family (e.g. blocks/sidebar-07/nav-main.marko).
// Our SidebarMenuButton has no `size="sm"` variant, so this uses `text-sm`
// on the icon svg sizing is left at the button's default (still visually
// compact given the single-line rows). Deviation from the source, noted
// per block-porting rules.

<SidebarGroup class=input.class>
  <SidebarMenu>
    <for|item| of=input.items by=(item) => item.id>
      <SidebarMenuItem>
        <SidebarMenuButton href=item.url class="text-sm">
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linecap="round"
            stroke-linejoin="round"
            class="size-4"
          >
            <path d=item.icon/>
          </svg>
          <span>${item.title}</span>
        </SidebarMenuButton>
      </SidebarMenuItem>
    </for>
  </SidebarMenu>
</SidebarGroup>

import Avatar from "../../components/ui/avatar/avatar.marko";
import DropdownMenu from "../../components/ui/dropdown-menu/dropdown-menu.marko";
import SidebarMenu from "../../components/ui/sidebar/menu.marko";
import SidebarMenuItem from "../../components/ui/sidebar/menu-item.marko";
import SidebarMenuButton from "../../components/ui/sidebar/menu-button.marko";

export interface NavUserData {
  name: string;
  email: string;
  avatar: string;
}

export interface Input {
  user: NavUserData;
}

// The dropdown-menu `<@item>` attr tag accepts a markup `content` body plus
// a `class` override on label entries (see
// ui/dropdown-menu/dropdown-menu.marko), so the source's rich
// DropdownMenuLabel — avatar + name/email, with `p-0 font-normal` replacing
// the default padded/muted label classes — ports faithfully instead of
// being flattened to a plain string label.
//
// Width: the source sizes DropdownMenuContent with
// `w-(--radix-dropdown-menu-trigger-width)`, a Radix CSS var mirroring the
// trigger's measured width. zag's popper exposes the same measurement as
// `--reference-width` on the positioner (see @zag-js/popper
// get-placement.js/get-styles.js), so `w-(--reference-width)` is the
// visual-equivalent mapping for our primitive.

<SidebarMenu>
  <SidebarMenuItem>
    <DropdownMenu class="w-(--reference-width) min-w-56 rounded-lg">
      <@trigger|triggerProps|>
        <SidebarMenuButton
          ...triggerProps
          size="lg"
          class="data-[state=open]:bg-sidebar-accent data-[state=open]:text-sidebar-accent-foreground"
        >
          <Avatar src=input.user.avatar alt=input.user.name fallback="CN" class="size-8 rounded-lg"/>
          <div class="grid flex-1 text-left text-sm leading-tight">
            <span class="truncate font-medium">${input.user.name}</span>
            <span class="truncate text-xs">${input.user.email}</span>
          </div>
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linecap="round"
            stroke-linejoin="round"
            class="ml-auto size-4"
          >
            <path d="m7 15 5 5 5-5"/>
            <path d="m7 9 5-5 5 5"/>
          </svg>
        </SidebarMenuButton>
      </@trigger>
      <@item type="label" class="p-0 font-normal">
        <div class="flex items-center gap-2 px-1 py-1.5 text-left text-sm">
          <Avatar src=input.user.avatar alt=input.user.name fallback="CN" class="size-8 rounded-lg"/>
          <div class="grid flex-1 text-left text-sm leading-tight">
            <span class="truncate font-medium">${input.user.name}</span>
            <span class="truncate text-xs">${input.user.email}</span>
          </div>
        </div>
      </@item>
      <@item type="separator"/>
      <@item type="item" value="upgrade" label="Upgrade to Pro"/>
      <@item type="separator"/>
      <@item type="item" value="account" label="Account"/>
      <@item type="item" value="billing" label="Billing"/>
      <@item type="item" value="notifications" label="Notifications"/>
      <@item type="separator"/>
      <@item type="item" value="logout" label="Log out"/>
    </DropdownMenu>
  </SidebarMenuItem>
</SidebarMenu>

import SidebarProvider from "../../components/ui/sidebar/provider.marko";
import AppSidebar from "./app-sidebar.marko";
import SiteHeader from "./site-header.marko";

// shadcn's source structure is:
//   SidebarProvider(flex-col, full width)
//     > SiteHeader (full-width bar, sibling BEFORE the sidebar/inset row)
//     > div.flex.flex-1 > [AppSidebar, SidebarInset]
// Our SidebarProvider's root div is hardcoded to `flex` (row) and only
// exposes `@sidebar`/`@content` slots inside that row, so it cannot host a
// full-width sibling above the row. To reproduce the source's visual
// structure exactly, SiteHeader is rendered as a sibling BEFORE
// SidebarProvider (not inside it), with the outer wrapper switched to
// `flex flex-col`; SidebarProvider's own `flex w-full` root then serves as
// the source's `div.flex.flex-1` row. This keeps the shared provider
// component untouched while matching the source's rendered DOM shape:
// full-width header on top, sidebar + inset row below it. The sidebar's
// `top-(--header-height)` offset (see app-sidebar.marko) then docks it
// visually under the header.
//
// `toggle` is only exposed inside the provider's `@sidebar`/`@content`
// render-prop scopes, so it is captured into a page-level variable via the
// `@sidebar` slot and reused by the SiteHeader rendered outside the
// provider. There is no SidebarInset sub-part, so the inset panel is
// composed here from plain markup, following blocks/sidebar-07/page.marko
// and blocks/sidebar-15/page.marko.

<let/toggleSidebar=(): void => {}/>

<div class="flex min-h-svh flex-col" style="--header-height:calc(var(--spacing)*14)">
  <SiteHeader toggle=toggleSidebar/>
  <SidebarProvider width="16rem" class="flex-1">
    <@sidebar|{ open, toggle }|>
      <script>
        toggleSidebar = toggle;
      </script>
      <AppSidebar open=open/>
    </@sidebar>
    <@content|{ }|>
      <div class="flex min-w-0 flex-1 flex-col">
        <div class="flex flex-1 flex-col gap-4 p-4">
          <div class="grid auto-rows-min gap-4 md:grid-cols-3">
            <div class="aspect-video rounded-xl bg-muted/50"></div>
            <div class="aspect-video rounded-xl bg-muted/50"></div>
            <div class="aspect-video rounded-xl bg-muted/50"></div>
          </div>
          <div class="min-h-[100vh] flex-1 rounded-xl bg-muted/50 md:min-h-min"></div>
        </div>
      </div>
    </@content>
  </SidebarProvider>
</div>
